// GENERATED by scripts/build_workflows.mjs from n8n/src - do not edit in the n8n UI.

// ---- main

const q = $input.first().json.query || {};
const token = $env.WHATSAPP_VERIFY_TOKEN;
const ok = q['hub.mode'] === 'subscribe' && !!token && q['hub.verify_token'] === token;
return [{ json: { code: ok ? 200 : 403, body: ok ? String(q['hub.challenge'] || '') : 'forbidden' } }];

// GENERATED by scripts/build_workflows.mjs from n8n/src - do not edit in the n8n UI.

// ---- core/signature.js
// Meta webhook signature check (X-Hub-Signature-256 = "sha256=" + HMAC-SHA256(rawBody, APP_SECRET)).
// `crypto` is passed in so this module stays pure and testable outside n8n.
function verifySignature(rawBody, header, appSecret, crypto) {
  if (!appSecret || typeof header !== 'string' || !header.startsWith('sha256=')) return false;
  const body = Buffer.isBuffer(rawBody) ? rawBody : Buffer.from(String(rawBody ?? ''), 'utf8');
  const expected = crypto.createHmac('sha256', appSecret).update(body).digest();
  let given;
  try {
    given = Buffer.from(header.slice(7), 'hex');
  } catch (e) {
    return false;
  }
  return given.length === expected.length && crypto.timingSafeEqual(given, expected);
}

// ---- core/explode.js
// Split one Meta webhook POST into one item per inbound message.
// Meta can batch several entries/changes/messages in a single delivery, and
// sends delivery/read receipts ("statuses") which we drop here.
function explodeWebhook(body) {
  const out = [];
  if (!body || body.object !== 'whatsapp_business_account') return out;
  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      if (change.field !== 'messages') continue;
      const value = change.value || {};
      const contacts = value.contacts || [];
      for (const message of value.messages || []) {
        const contact = contacts.find((c) => c.wa_id === message.from) || contacts[0] || {};
        out.push({
          wa_id: message.from,
          msg_id: message.id,
          timestamp: message.timestamp,
          phone_number_id: (value.metadata || {}).phone_number_id,
          message,
        });
      }
    }
  }
  return out;
}

// ---- core/normalize.js
// Reduce any inbound WhatsApp message to the router's input shape:
// { kind, id, text, lat, lon, lang_guess }
const DEVANAGARI = /[ऀ-ॿ]/;
const LATIN = /[A-Za-z]/;

function guessLang(text) {
  if (!text) return null;
  if (DEVANAGARI.test(text)) return 'hi';
  if (LATIN.test(text)) return 'en';
  return null;
}

function normalizeMessage(message) {
  const m = message || {};
  const base = { kind: 'unsupported', id: null, text: null, lat: null, lon: null, lang_guess: null, raw_type: m.type || null };
  switch (m.type) {
    case 'text': {
      const text = ((m.text || {}).body || '').trim();
      return { ...base, kind: 'text', text, lang_guess: guessLang(text) };
    }
    case 'interactive': {
      const i = m.interactive || {};
      if (i.type === 'button_reply' && i.button_reply) {
        return { ...base, kind: 'button', id: i.button_reply.id, text: i.button_reply.title };
      }
      if (i.type === 'list_reply' && i.list_reply) {
        return { ...base, kind: 'list', id: i.list_reply.id, text: i.list_reply.title };
      }
      return base;
    }
    case 'button': // quick-reply button on a template message
      return { ...base, kind: 'button', id: (m.button || {}).payload || null, text: (m.button || {}).text || null };
    case 'location': {
      const loc = m.location || {};
      return { ...base, kind: 'location', lat: Number(loc.latitude), lon: Number(loc.longitude) };
    }
    default:
      return base; // audio, voice, image, video, sticker, document, contacts, reaction, ...
  }
}

// ---- main

const crypto = require('crypto');
const first = $input.first();
// The raw body arrives inline as base64 (in-memory binary data). Read it directly:
// the getBinaryDataBuffer() helper round-trips through the task broker and was
// seen to hang for good after an overload, silently dropping every later message.
const bin = first.binary && first.binary.data;
let raw = '';
if (bin && bin.data && !bin.id) raw = Buffer.from(bin.data, 'base64').toString('utf8');
else if (bin) raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const headers = first.json.headers || {};
if (!verifySignature(raw, headers['x-hub-signature-256'], $env.META_APP_SECRET, crypto)) {
  return []; // unsigned or forged request: drop silently, never reply
}
return explodeWebhook(first.json.body).map((m) => ({
  json: { wa_id: m.wa_id, msg_id: m.msg_id, input: normalizeMessage(m.message) },
}));

// GENERATED by scripts/build_workflows.mjs from n8n/src - do not edit in the n8n UI.

// ---- core/route.js
// Decide what to do with one normalised inbound message.
// Precedence (first match wins):
//   unsupported type -> global command -> core ids (core:/lang:/fb:) ->
//   service id prefix -> location handler -> session state owner ->
//   free text -> LLM (if enabled) -> main menu
const GLOBAL_COMMANDS = new Set([
  'hi', 'hii', 'hello', 'hey', 'helo', 'namaste', 'namaskar', 'menu', 'start', 'help', '0', 'home',
  'नमस्ते', 'नमस्कार', 'हेलो', 'हाय', 'मेनू', 'मेन्यू', 'शुरू',
]);
const LANG_COMMANDS = { english: 'en', 'अंग्रेज़ी': 'en', 'अंग्रेजी': 'en', hindi: 'hi', 'हिंदी': 'hi', 'हिन्दी': 'hi' };

function normText(text) {
  return String(text || '').trim().toLowerCase().replace(/[!.?।\s]+$/u, '');
}

function prefixOf(value, sep) {
  if (!value) return null;
  const i = value.indexOf(sep);
  return i > 0 ? value.slice(0, i) : null;
}

// Service whose registry keyword appears in the text (Latin: whole word;
// Devanagari: substring, since Hindi words take suffixes). Lower menu_order wins.
function keywordService(services, text) {
  const t = ` ${String(text || '').toLowerCase().replace(/[^\p{L}\p{M}\p{N}]+/gu, ' ')} `;
  const sorted = (services || []).slice().sort((a, b) => (a.menu_order || 0) - (b.menu_order || 0));
  for (const s of sorted) {
    for (const k of s.keywords || []) {
      const kw = String(k).toLowerCase().trim();
      if (!kw) continue;
      if (/[\u0900-\u097F]/.test(kw) ? t.includes(kw) : t.includes(` ${kw} `)) return s;
    }
  }
  return null;
}

function decideRoute({ input, state, services, isAdmin, llmEnabled }) {
  const svcByPrefix = new Map((services || []).map((s) => [s.id_prefix, s]));

  if (input.kind === 'unsupported') return { action: 'unsupported' };

  if (input.kind === 'text') {
    const t = normText(input.text);
    if (GLOBAL_COMMANDS.has(t)) return { action: 'menu' };
    if (LANG_COMMANDS[t]) return { action: 'lang', lang: LANG_COMMANDS[t] };
  }

  if (input.id) {
    const id = input.id;
    if (id === 'core:menu') return { action: 'menu' };
    if (id.startsWith('lang:')) return { action: 'lang', lang: id.slice(5) === 'hi' ? 'hi' : 'en' };
    if (id.startsWith('fb:')) {
      const [, vote, svc] = id.split(':');
      return { action: 'feedback', rating: vote === 'up' ? 1 : -1, service_key: svc || null };
    }
    const svc = svcByPrefix.get(prefixOf(id, ':'));
    if (svc) {
      if (id.split(':')[1] === 'adm' && !isAdmin) return { action: 'not_allowed' };
      return { action: 'service', service: svc };
    }
    return { action: 'menu', reason: 'stale_id' }; // button from a disabled/unknown service
  }

  const stateOwner = svcByPrefix.get(prefixOf(state, '.'));

  if (input.kind === 'location') {
    if (stateOwner && stateOwner.accepts_location) return { action: 'service', service: stateOwner };
    const handler = (services || []).find((s) => s.accepts_location);
    return handler ? { action: 'service', service: handler } : { action: 'menu' };
  }

  if (stateOwner) return { action: 'service', service: stateOwner };

  if (input.kind === 'text' && input.text) {
    const byKeyword = keywordService(services, input.text);
    if (byKeyword) return { action: 'service', service: byKeyword, via: 'keyword' };
    return llmEnabled ? { action: 'llm' } : { action: 'menu', reason: 'no_llm' };
  }
  return { action: 'menu' };
}

// ---- core/menu.js
// Main menu built from the service registry.
//   1 enabled service  -> open that service directly (no one-button menu)
//   2-3 services       -> reply buttons (+ language toggle when there is room)
//   >3 services        -> list message (+ language toggle row)
// Every service must answer the id '<id_prefix>:open' with its own menu.
function tpl(templates, key, lang) {
  const row = (templates || {})[key];
  return row ? row[lang] || row.en || key : key;
}

function openId(service) {
  return `${service.id_prefix}:open`;
}

function buildMainMenu(services, lang, templates) {
  const list = (services || []).slice().sort((a, b) => (a.menu_order - b.menu_order) || a.service_key.localeCompare(b.service_key));
  const title = (s) => (lang === 'hi' ? s.title_hi : s.title_en) || s.title_en;
  const desc = (s) => (lang === 'hi' ? s.description_hi : s.description_en) || '';
  const otherLang = lang === 'hi' ? 'en' : 'hi';
  const langToggle = { id: `lang:${otherLang}`, title: tpl(templates, 'btn_lang_other', lang) };

  if (list.length === 0) {
    return { kind: 'messages', messages: [{ type: 'text', body: tpl(templates, 'error_apology', lang) }] };
  }
  if (list.length === 1) {
    return { kind: 'open_service', service: list[0] };
  }
  if (list.length <= 3) {
    const buttons = list.map((s) => ({ id: openId(s), title: title(s) }));
    if (buttons.length < 3) buttons.push(langToggle);
    return { kind: 'messages', messages: [{ type: 'buttons', body: tpl(templates, 'menu_prompt', lang), buttons }] };
  }
  const rows = list.slice(0, 9).map((s) => ({ id: openId(s), title: title(s), description: desc(s) }));
  rows.push({ id: langToggle.id, title: langToggle.title, description: '' });
  return {
    kind: 'messages',
    messages: [{
      type: 'list',
      body: tpl(templates, 'menu_prompt', lang),
      button: tpl(templates, 'menu_button', lang),
      sections: [{ title: tpl(templates, 'menu_section', lang), rows }],
    }],
  };
}

// ---- core/contract.js
// Service contract validation. A service output that breaks the contract is
// never sent; the router replies with an apology and alerts the admins.
const MESSAGE_TYPES = new Set(['text', 'buttons', 'list', 'location', 'location_request']);
const SHARED_ID_PREFIXES = ['core:', 'lang:', 'fb:'];

function idAllowed(id, prefix) {
  return typeof id === 'string' && (id.startsWith(`${prefix}:`) || SHARED_ID_PREFIXES.some((p) => id.startsWith(p)));
}

function validateServiceOutput(out, prefix) {
  const errors = [];
  if (!out || typeof out !== 'object') return ['output is not an object'];
  if (!Array.isArray(out.messages)) errors.push('messages must be an array');
  for (const [i, m] of (out.messages || []).entries()) {
    if (!m || !MESSAGE_TYPES.has(m.type)) { errors.push(`messages[${i}].type invalid`); continue; }
    if ((m.type === 'text' || m.type === 'buttons' || m.type === 'list' || m.type === 'location_request') && !m.body) {
      errors.push(`messages[${i}].body missing`);
    }
    if (m.type === 'buttons') {
      if (!Array.isArray(m.buttons) || m.buttons.length < 1 || m.buttons.length > 3) errors.push(`messages[${i}] needs 1-3 buttons`);
      for (const b of m.buttons || []) if (!idAllowed(b.id, prefix)) errors.push(`messages[${i}] button id "${b.id}" outside prefix "${prefix}"`);
    }
    if (m.type === 'list') {
      const rows = (m.sections || []).flatMap((s) => s.rows || []);
      if (rows.length < 1 || rows.length > 10) errors.push(`messages[${i}] needs 1-10 list rows`);
      for (const r of rows) if (!idAllowed(r.id, prefix)) errors.push(`messages[${i}] row id "${r.id}" outside prefix "${prefix}"`);
    }
    if (m.type === 'location' && (typeof m.lat !== 'number' || typeof m.lon !== 'number')) errors.push(`messages[${i}] location needs numeric lat/lon`);
  }
  if (out.next_state != null && !(typeof out.next_state === 'string' && out.next_state.startsWith(`${prefix}.`))) {
    errors.push(`next_state "${out.next_state}" must start with "${prefix}."`);
  }
  if (out.context != null && (typeof out.context !== 'object' || Array.isArray(out.context))) errors.push('context must be an object');
  if (out.done != null && typeof out.done !== 'boolean') errors.push('done must be boolean');
  // log: { subtype?, resolved?, detail?, llm_tokens?, unanswered_reason? } feeds analytics
  const log = out.log;
  if (log != null) {
    if (typeof log !== 'object' || Array.isArray(log)) errors.push('log must be an object');
    else {
      for (const k of ['subtype', 'detail', 'unanswered_reason']) {
        if (log[k] != null && (typeof log[k] !== 'string' || log[k].length > 64)) errors.push(`log.${k} must be a string of at most 64 chars`);
      }
      if (log.llm_tokens != null && !(Number.isInteger(log.llm_tokens) && log.llm_tokens >= 0)) errors.push('log.llm_tokens must be a non-negative integer');
    }
  }
  return errors;
}

// ---- core/turn.js
// Turn orchestration: pure functions the router's Code nodes call.
//
//   decideTurn()  -> { action: 'stop' | 'reply' | 'service' | 'llm', env, ... }
//   afterLlm()    -> same shape (service or reply)
//   afterService()-> { messages, next_state, context, done, log, alert }
//   finalizeTurn()-> { send, end, alert }
//
// `env` (the turn envelope) travels between nodes and carries everything the
// later steps need, so no step has to re-query the database.
// Depends on: decideRoute (route.js), buildMainMenu/tpl (menu.js),
// validateServiceOutput (contract.js). Inside n8n those are concatenated into
// the same Code node; under node:test they are required here.
const _turnDeps = (typeof require === 'function' && typeof decideRoute === 'undefined')
  ? { ...require('./route.js'), ...require('./menu.js'), ...require('./contract.js') }
  : null;
const _decideRoute = (a) => (_turnDeps ? _turnDeps.decideRoute(a) : decideRoute(a));
const _buildMainMenu = (a, b, c) => (_turnDeps ? _turnDeps.buildMainMenu(a, b, c) : buildMainMenu(a, b, c));
const _tpl = (a, b, c) => (_turnDeps ? _turnDeps.tpl(a, b, c) : tpl(a, b, c));
const _validate = (a, b) => (_turnDeps ? _turnDeps.validateServiceOutput(a, b) : validateServiceOutput(a, b));

function istNow(date) {
  const d = date || new Date();
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hour12: false,
  }).formatToParts(d);
  const get = (t) => (parts.find((p) => p.type === t) || {}).value;
  const hour = get('hour') === '24' ? '00' : get('hour');
  return `${get('year')}-${get('month')}-${get('day')} ${hour}:${get('minute')}`;
}

function splitContext(ctx) {
  const all = ctx && typeof ctx === 'object' ? ctx : {};
  const { __core, ...service } = all;
  return { service, core: __core && typeof __core === 'object' ? __core : {} };
}

function buildEnv(item, turn, flags) {
  const { service, core } = splitContext(turn.context);
  return {
    wa_id: item.wa_id,
    msg_id: item.msg_id,
    input: item.input,
    wa_hash: turn.wa_hash,
    version: turn.version,
    lang: turn.lang === 'en' ? 'en' : 'hi',
    state: turn.state || null,
    context: service,
    core_ctx: core,
    first_contact: !!turn.first_contact,
    is_admin: !!turn.is_admin,
    services: turn.services || [],
    templates: turn.templates || {},
    llm_enabled: !!(flags && flags.llmEnv) && String((turn.settings || {}).llm_enabled) !== 'false',
    received_ms: (flags && flags.nowMs) || Date.now(),
  };
}

function t(env, key) {
  return _tpl(env.templates, key, env.lang);
}

// Main menu, or straight into the only service (single-service rule).
function menuOrOpen(env, pre, extra) {
  const m = _buildMainMenu(env.services, env.lang, env.templates);
  if (m.kind === 'open_service') {
    return { action: 'service', env, service: m.service, pre,
             input: { kind: 'open', id: `${m.service.id_prefix}:open`, text: null, lat: null, lon: null }, ...extra };
  }
  return { action: 'reply', env, pre, messages: m.messages, state: null, context: {}, service_key: null, done: false, ...extra };
}

function decideTurn(item, turn, flags) {
  if (!turn || turn.is_dup) return { action: 'stop', reason: 'duplicate' };
  const env = buildEnv(item, turn, flags);
  if (turn.rate_limited) {
    if (!turn.rate_notice) return { action: 'stop', reason: 'rate_limited' };
    return { action: 'reply', env, pre: [], messages: [{ type: 'text', body: t(env, 'rate_limited') }],
             state: env.state, context: env.context, service_key: null, done: false, skip_end: true };
  }
  const route = _decideRoute({ input: env.input, state: env.state, services: env.services, isAdmin: env.is_admin, llmEnabled: env.llm_enabled });
  const via = env.input.kind === 'text' ? 'text' : env.input.kind;
  switch (route.action) {
    case 'unsupported':
      return menuOrOpen(env, [{ type: 'text', body: t(env, 'unsupported') }], { subtype: 'unsupported' });
    case 'lang':
      env.lang = route.lang;
      return menuOrOpen(env, [{ type: 'text', body: t(env, 'lang_switched') }], { set_lang: route.lang });
    case 'feedback':
      return { action: 'reply', env, pre: [], messages: [{ type: 'text', body: t(env, 'feedback_thanks') }],
               state: env.state, context: env.context, service_key: route.service_key, done: false,
               feedback_rating: route.rating, subtype: 'feedback' };
    case 'not_allowed':
      return menuOrOpen(env, [{ type: 'text', body: t(env, 'not_allowed') }]);
    case 'service':
      return { action: 'service', env, service: route.service, pre: [], input: env.input, via: route.via || via };
    case 'llm':
      return { action: 'llm', env };
    case 'menu':
    default:
      return menuOrOpen(env, [], route.reason === 'no_llm' ? { unanswered_reason: 'llm_disabled' } : {});
  }
}

function afterLlm(decision, result) {
  const env = decision.env;
  const r = result || {};
  if (r.ok) {
    const service = env.services.find((s) => s.service_key === r.service_key);
    if (service) {
      return { action: 'service', env, service, pre: [], via: 'llm', llm_tokens: r.tokens || 0,
               input: { ...env.input, intent: { subtype: r.subtype, slots: r.slots || {} } } };
    }
  }
  return menuOrOpen(env, [{ type: 'text', body: t(env, 'not_understood') }],
                    { unanswered_reason: r.reason || 'no_service', llm_tokens: r.tokens || 0 });
}

function serviceInput(decision) {
  const env = decision.env;
  return {
    wa_hash: env.wa_hash,
    lang: env.lang,
    // A different service's pending state is not this service's business.
    state: env.state && env.state.startsWith(`${decision.service.id_prefix}.`) ? env.state : null,
    context: env.state && env.state.startsWith(`${decision.service.id_prefix}.`) ? env.context : {},
    now_iso: new Date(env.received_ms).toISOString(),
    now_ist: istNow(new Date(env.received_ms)),
    is_admin: env.is_admin,
    input: decision.input,
  };
}

function afterService(decision, out, errorMessage) {
  const env = decision.env;
  const key = decision.service.service_key;
  const fail = (why) => ({
    messages: [{ type: 'text', body: t(env, 'error_apology') }],
    next_state: env.state, context: env.context, done: false,
    log: { subtype: 'error', resolved: false },
    alert: `Service "${key}" failed for input ${JSON.stringify(decision.input && (decision.input.id || decision.input.kind))}: ${why}`,
  });
  if (errorMessage) return fail(errorMessage);
  const errors = _validate(out, decision.service.id_prefix);
  if (errors.length) return fail(`contract violation: ${errors.join('; ')}`);
  return {
    messages: out.messages,
    next_state: out.next_state == null ? null : out.next_state,
    context: out.context || {},
    done: !!out.done,
    log: out.log || {},
    alert: null,
  };
}

function feedbackPrompt(env, serviceKey) {
  return {
    type: 'buttons',
    body: t(env, 'feedback_prompt'),
    buttons: [
      { id: `fb:up:${serviceKey}`, title: t(env, 'btn_helpful') },
      { id: `fb:down:${serviceKey}`, title: t(env, 'btn_not_helpful') },
      { id: 'core:menu', title: t(env, 'btn_menu') },
    ],
  };
}

// decision: output of decideTurn/afterLlm; result: afterService() output or null for core replies.
function finalizeTurn(decision, result) {
  const env = decision.env;
  const serviceKey = decision.service ? decision.service.service_key : decision.service_key || null;
  const r = result || { messages: decision.messages || [], next_state: decision.state, context: decision.context || {}, done: !!decision.done, log: {} };
  const coreCtx = { ...env.core_ctx };
  const messages = [];
  if (env.first_contact) messages.push({ type: 'text', body: t(env, 'welcome_notice') });
  messages.push(...(decision.pre || []), ...(r.messages || []));
  if (r.done && serviceKey && !coreCtx.fb_asked) {
    messages.push(feedbackPrompt(env, serviceKey));
    coreCtx.fb_asked = true;
  }
  const log = r.log || {};
  return {
    send: { to: env.wa_id, wa_hash: env.wa_hash, lang: env.lang, service_key: serviceKey, messages },
    end: decision.skip_end ? null : {
      wa_hash: env.wa_hash,
      version: env.version,
      state: r.next_state || null,
      context: { ...(r.context || {}), __core: coreCtx },
      in_msg_id: env.msg_id,
      service_key: serviceKey,
      subtype: log.subtype || decision.subtype || null,
      via: decision.via || (env.input.kind === 'text' ? 'text' : env.input.kind),
      resolved: log.resolved != null ? !!log.resolved : !(decision.unanswered_reason || log.unanswered_reason),
      detail: log.detail || null,
      // classifier tokens (router) + any tokens the service spent itself (e.g. Q&A)
      llm_tokens: ((decision.llm_tokens || 0) + (log.llm_tokens || 0)) || null,
      latency_ms: Math.max(0, Date.now() - env.received_ms),
      set_lang: decision.set_lang || null,
      feedback_rating: decision.feedback_rating == null ? null : decision.feedback_rating,
      unanswered_reason: decision.unanswered_reason || log.unanswered_reason || null,
      text: env.input.kind === 'text' ? env.input.text : null,
    },
    alert: r.alert || null,
  };
}

// ---- main

const src = $('Verify & Explode').item.json;
const d = decideTurn(src, $json.turn, { llmEnv: String($env.LLM_ENABLED ?? 'true') !== 'false', nowMs: Date.now() });
const route = { stop: 0, reply: 1, service: 2, llm: 3 }[d.action];
// service calls carry the service's input at the top level plus the turn in _router
return { json: d.action === 'service' ? { ...serviceInput(d), _router: d, route } : { ...d, route } };

// GENERATED by scripts/build_workflows.mjs from n8n/src - do not edit in the n8n UI.

// ---- core/route.js
// Decide what to do with one normalised inbound message.
// Precedence (first match wins):
//   unsupported type -> global command -> core ids (core:/lang:/fb:) ->
//   service id prefix -> location handler -> session state owner ->
//   free text -> LLM (if enabled) -> main menu
const GLOBAL_COMMANDS = new Set([
